class Solution:
    def oddEvenList(self, head):
        if not head or not head.next: return head
        odd=head;even=head.next;even_head=even
        while even and even.next:
            odd.next=even.next;odd=odd.next
            even.next=odd.next;even=even.next
        odd.next=even_head
        return head

class Solution {
    public ListNode oddEvenList(ListNode head) {
        if(head==null||head.next==null)return head;
        ListNode odd=head,even=head.next,evenHead=even;
        while(even!=null&&even.next!=null){odd.next=even.next;odd=odd.next;even.next=odd.next;even=even.next;}
        odd.next=evenHead;return head;
    }
}

from functools import lru_cache
class Solution:
    def longestIncreasingPath(self, matrix: list[list[int]]) -> int:
        if not matrix or not matrix[0]: return 0
        m,n=len(matrix),len(matrix[0])
        @lru_cache(None)
        def dfs(r,c):
            best=1
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<m and 0<=nc<n and matrix[nr][nc]>matrix[r][c]:
                    best=max(best,1+dfs(nr,nc))
            return best
        return max(dfs(r,c) for r in range(m) for c in range(n))

class Solution {
    private int[][] a,memo; private int m,n; private final int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};
    public int longestIncreasingPath(int[][] matrix) {
        if(matrix.length==0||matrix[0].length==0)return 0;
        a=matrix;m=a.length;n=a[0].length;memo=new int[m][n];int ans=0;
        for(int r=0;r<m;r++)for(int c=0;c<n;c++)ans=Math.max(ans,dfs(r,c));return ans;
    }
    private int dfs(int r,int c){if(memo[r][c]!=0)return memo[r][c];int best=1;
        for(int[] d:dirs){int x=r+d[0],y=c+d[1];if(x>=0&&x<m&&y>=0&&y<n&&a[x][y]>a[r][c])best=Math.max(best,1+dfs(x,y));}
        return memo[r][c]=best;
    }
}

class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        slots=1
        for token in preorder.split(','):
            if slots==0: return False
            slots-=1
            if token!='#': slots+=2
        return slots==0

class Solution {
    public boolean isValidSerialization(String preorder) {
        long slots=1;
        for(String token:preorder.split(",")){if(slots==0)return false;slots--;if(!token.equals("#"))slots+=2;}
        return slots==0;
    }
}

from collections import defaultdict
class Solution:
    def findItinerary(self, tickets: list[list[str]]) -> list[str]:
        graph=defaultdict(list)
        for a,b in tickets: graph[a].append(b)
        for a in graph: graph[a].sort(reverse=True)
        route=[]
        def dfs(a):
            while graph[a]: dfs(graph[a].pop())
            route.append(a)
        dfs("JFK")
        return route[::-1]

import java.util.*;
class Solution {
    private Map<String,PriorityQueue<String>> graph; private List<String> route;
    public List<String> findItinerary(List<List<String>> tickets) {
        graph=new HashMap<>();route=new ArrayList<>();
        for(List<String> t:tickets)graph.computeIfAbsent(t.get(0),k->new PriorityQueue<>()).offer(t.get(1));
        dfs("JFK");Collections.reverse(route);return route;
    }
    private void dfs(String a){PriorityQueue<String> q=graph.get(a);while(q!=null&&!q.isEmpty())dfs(q.poll());route.add(a);}
}

class Solution:
    def increasingTriplet(self, nums: list[int]) -> bool:
        first=second=float('inf')
        for x in nums:
            if x<=first: first=x
            elif x<=second: second=x
            else: return True
        return False

class Solution {
    public boolean increasingTriplet(int[] nums) {
        long first=Long.MAX_VALUE,second=Long.MAX_VALUE;
        for(int x:nums){if(x<=first)first=x;else if(x<=second)second=x;else return true;}
        return false;
    }
}
